<meta name="viewport" content="width=device-width,initial-scale=1">
<script>
  // No-flash theme bootstrap: set data-theme BEFORE <style> parses so first
  // paint uses the right colors. Order: localStorage > OS preference > dark.
  (function(){
    try{
      var saved = localStorage.getItem('lawpoc-admin-theme');
      var theme = saved || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
      document.documentElement.setAttribute('data-theme', theme);
    }catch(e){ document.documentElement.setAttribute('data-theme', 'dark'); }
  })();
</script>
<style>
:root{
  /* Core tokens (light defaults) */
  --bg:#f6f7f9;--card:#fff;--ink:#0f172a;--muted:#64748b;--muted-2:#94a3b8;
  --bd:#e2e8f0;--bd-soft:#f1f5f9;
  --pri:#0f766e;--pri-2:#0d9488;--warn:#b45309;--err:#b91c1c;--ok:#15803d;

  /* Component tokens (light) */
  --header-bg:#0f172a;--header-fg:#fff;--crumb-fg:#94a3b8;
  --hover-bg:#f1f5f9;--th-bg:#f8fafc;
  --row-divider:#f1f5f9;--row-hover-bg:#fafbfc;
  --mono-fg:#475569;--chunk-text:#334155;
  --modal-overlay:rgba(15,23,42,.5);--modal-card:#fff;--modal-ft-bg:#f8fafc;
  --file-preview-bg:#f8fafc;--input-bg:#fff;
  --toast-bg:#0f172a;--toast-fg:#fff;
  --spinner-border:#fff;
  --sticky-act-shadow:rgba(15,23,42,.15);

