  --shadow-md:0 4px 12px rgba(15,23,42,.08);
}
[data-theme="dark"]{
  --bg:#0e1422;--card:#161e35;--ink:#f1f5f9;--muted:#94a3b8;--muted-2:#64748b;
  --bd:rgba(148,163,184,.15);--bd-soft:rgba(148,163,184,.08);
  --pri:#2dd4bf;--pri-2:#14b8a6;--warn:#fbbf24;--err:#f87171;--ok:#4ade80;

  --header-bg:#050a17;--header-fg:#f1f5f9;--crumb-fg:#64748b;
  --hover-bg:rgba(148,163,184,.08);--th-bg:rgba(148,163,184,.05);
