  --mono-fg:#cbd5e1;--chunk-text:#cbd5e1;
  --modal-overlay:rgba(0,0,0,.7);--modal-card:#161e35;--modal-ft-bg:#0e1422;
  --file-preview-bg:#0e1422;--input-bg:#0e1422;
  --toast-bg:#f1f5f9;--toast-fg:#0f172a;
  --spinner-border:#0e1422;
  --sticky-act-shadow:rgba(0,0,0,.5);

  --badge-ready-bg:rgba(34,197,94,.18);     --badge-ready-fg:#4ade80;
  --badge-pending-bg:rgba(245,158,11,.18);   --badge-pending-fg:#fbbf24;
  --badge-failed-bg:rgba(239,68,68,.18);    --badge-failed-fg:#f87171;
  --badge-processing-bg:rgba(59,130,246,.18);--badge-processing-fg:#60a5fa;

  --shadow-sm:0 1px 2px rgba(0,0,0,.4);
  --shadow-md:0 4px 12px rgba(0,0,0,.4);
}
*{box-sizing:border-box}
body{font:14px/1.5 -apple-system,"SF Pro Text","Inter",system-ui,sans-serif;margin:0;background:var(--bg);color:var(--ink);transition:background-color .2s ease,color .2s ease}
header{background:var(--header-bg);color:var(--header-fg);padding:14px 24px;display:flex;align-items:center;gap:16px;box-shadow:0 1px 0 rgba(0,0,0,.2);transition:background-color .2s ease}
header h1{font-size:16px;font-weight:600;margin:0;letter-spacing:.2px}
header .crumb{color:var(--crumb-fg);font-size:12px;margin-left:auto}
header .theme-toggle{margin-left:8px;background:transparent;color:var(--header-fg);border:1px solid rgba(255,255,255,.18);border-radius:8px;height:32px;width:32px;padding:0;cursor:pointer;font-size:14px;display:inline-flex;align-items:center;justify-content:center;transition:all .15s}
header .theme-toggle:hover{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.35)}
.wrap{max-width:1280px;margin:0 auto;padding:24px}
.toolbar{display:flex;gap:8px;align-items:center;margin-bottom:16px;flex-wrap:wrap}
.toolbar input,.toolbar select{height:36px;padding:0 12px;border:1px solid var(--bd);border-radius:8px;background:var(--input-bg);font:inherit;color:var(--ink);outline:none;transition:border-color .15s,box-shadow .15s}
.toolbar input:focus,.toolbar select:focus{border-color:var(--pri-2);box-shadow:0 0 0 3px rgba(13,148,136,.2)}
.toolbar input.search{flex:1;min-width:200px}

.similarity-bar{display:inline-block;height:6px;border-radius:3px;background:var(--bd);width:60px;vertical-align:middle;margin-right:6px;position:relative;overflow:hidden}
.similarity-bar>span{position:absolute;left:0;top:0;bottom:0;background:var(--pri)}
.chunk-preview{font-size:11px;color:var(--muted);margin-top:4px;line-height:1.4;max-width:420px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.btn{height:36px;padding:0 14px;border:0;border-radius:8px;background:var(--pri);color:#fff;font:inherit;font-weight:500;cursor:pointer;display:inline-flex;align-items:center;gap:6px;transition:background-color .15s,box-shadow .15s,transform .05s}
.btn:hover{background:var(--pri-2)}
.btn:active{transform:translateY(1px)}
.btn.ghost{background:transparent;color:var(--ink);border:1px solid var(--bd)}
.btn.ghost:hover{background:var(--hover-bg)}
.btn.warn{background:var(--warn)}
.btn.danger{background:var(--err)}
