.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.chunk-list{margin-top:8px;max-height:340px;overflow-y:auto;border:1px solid var(--bd);border-radius:6px;background:var(--input-bg)}
.chunk{padding:10px 12px;border-bottom:1px solid var(--bd-soft);font-size:12px}
.chunk:last-child{border-bottom:0}
.chunk .ci{color:var(--muted);font-family:ui-monospace,monospace;font-size:11px}
.chunk .cp{color:var(--chunk-text);margin-top:4px;line-height:1.4}
.toast{position:fixed;bottom:20px;right:20px;background:var(--toast-bg);color:var(--toast-fg);padding:12px 18px;border-radius:8px;font-size:13px;opacity:0;transform:translateY(10px);transition:all .2s;z-index:100;max-width:360px;box-shadow:var(--shadow-md)}
.toast.on{opacity:1;transform:translateY(0)}
.toast.err{background:var(--err);color:#fff}
.toast.ok{background:var(--ok);color:#fff}
mark.match{background:#fef08a;color:#713f12;padding:0 3px;border-radius:3px;font-weight:500}
.match-cell{max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;color:var(--mono-fg)}
.spin{display:inline-block;width:14px;height:14px;border:2px solid var(--spinner-border);border-top-color:transparent;border-radius:50%;animation:spin 1s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.loading{padding:40px;text-align:center;color:var(--muted)}
</style>
