    <button class="btn ghost" id="btn-refresh">↻ รีเฟรช</button>
  </div>
  <div class="card">
    <table>
      <thead><tr>
        <th style="width:130px">Doc No</th>
        <th>ชื่อไฟล์</th>
        <th style="width:110px">ความเหมือน</th>
        <th style="width:240px">Match</th>
        <th style="width:110px">Category</th>
        <th style="width:90px">Status</th>
        <th style="width:60px;text-align:right">Chunks</th>
        <th style="width:130px">อัปโหลด</th>
        <th class="sticky-act" style="width:200px"></th>
      </tr></thead>
      <tbody id="tbody">
        <tr><td colspan="9" class="loading">กำลังโหลด…</td></tr>
