</div>

<!-- View Modal -->
<div class="modal" id="m-view">
  <div class="box">
    <div class="hd"><h2 id="v-title">รายละเอียดเอกสาร</h2><button class="btn ghost sm" onclick="closeModal('m-view')">✕</button></div>
    <div class="bd" id="v-body"></div>
    <div class="ft"><button class="btn ghost" onclick="closeModal('m-view')">ปิด</button><button class="btn ghost" id="v-open-btn">เปิดไฟล์</button><button class="btn" id="v-edit-btn">แก้ไข</button></div>
  </div>
</div>

<!-- Edit Modal -->
<div class="modal" id="m-edit">
  <div class="box">
    <div class="hd"><h2>แก้ไขเอกสาร</h2><button class="btn ghost sm" onclick="closeModal('m-edit')">✕</button></div>
    <div class="bd">
      <input type="hidden" id="e-id">
      <div class="grid2">
        <div class="field"><label>Doc No</label><input id="e-doc_no" disabled><div class="hint">ไม่สามารถแก้ไขได้</div></div>
        <div class="field"><label>Status</label>
          <select id="e-status"><option value="ready">ready</option><option value="pending">pending</option><option value="failed">failed</option><option value="processing">processing</option></select>
        </div>
      </div>
      <div class="field"><label>ชื่อไฟล์</label><input id="e-file_name"></div>
      <div class="grid2">
        <div class="field"><label>Category</label><input id="e-category" placeholder="เช่น สัญญาเช่า, หนังสือมอบอำนาจ"></div>
        <div class="field"><label>Source</label><input id="e-source" placeholder="เช่น LINE OA, web upload"></div>
      </div>
    </div>
    <div class="ft">
      <button class="btn ghost" onclick="closeModal('m-edit')">ยกเลิก</button>
      <button class="btn" id="e-save">บันทึก</button>
    </div>
  </div>
</div>

<div class="toast" id="toast"></div>

<script>
const BASE = location.origin;
let allRows = [];
let statsCache = null;
let currentQuery = '';

// =========================================================================
// Theme switcher (toggle dark/light, persist in localStorage, respect OS pref)
// =========================================================================
const themeBtn = document.getElementById('btn-theme');
const themeIcon = document.getElementById('theme-icon');
const THEME_KEY = 'lawpoc-admin-theme';
const themeMedia = window.matchMedia('(prefers-color-scheme: light)');

function currentTheme(){ return document.documentElement.getAttribute('data-theme') || 'light'; }

function syncThemeIcon(theme){
  // Show the icon of the CURRENT theme so the button reflects page state
  themeIcon.textContent = theme === 'dark' ? '🌙' : '☀️';
  themeBtn.setAttribute('aria-label', theme === 'dark' ? 'เปลี่ยนเป็นโหมดสว่าง' : 'เปลี่ยนเป็นโหมดมืด');
  themeBtn.setAttribute('title', theme === 'dark' ? 'เปลี่ยนเป็นโหมดสว่าง' : 'เปลี่ยนเป็นโหมดมืด');
}

function applyTheme(theme, persist){
  document.documentElement.setAttribute('data-theme', theme);
  syncThemeIcon(theme);
  if(persist){ try{ localStorage.setItem(THEME_KEY, theme); }catch(e){} }
}

themeBtn.addEventListener('click', ()=>{
  applyTheme(currentTheme() === 'dark' ? 'light' : 'dark', true);
});

// Sync icon to whatever the head bootstrap set
syncThemeIcon(currentTheme());

// If user hasn't explicitly chosen, follow OS theme changes live
themeMedia.addEventListener('change', e=>{
  let saved = null;
  try{ saved = localStorage.getItem(THEME_KEY); }catch(err){}
  if(!saved) applyTheme(e.matches ? 'light' : 'dark', false);
});
// =========================================================================

function toast(msg, kind=''){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.className = 'toast on ' + kind;
  setTimeout(()=>t.className='toast '+kind, 2200);
}

async function api(path, opts){
  const r = await fetch(BASE + path, opts);
  if (!r.ok) throw new Error('HTTP '+r.status);
  return r.json();
}

function fmtDate(s){
  if(!s) return '—';
  const d = new Date(s);
  return d.toLocaleString('th-TH',{dateStyle:'short',timeStyle:'short'});
}

function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

async function loadStats(){
  try{
    const s = await api('/webhook/admin-stats');
    const v = (s && s.data) || s;
    if (typeof v === 'string') { try { v = JSON.parse(v); } catch {} }
    document.getElementById('stat-total').textContent = v.total??0;
    document.getElementById('stat-ready').textContent = v.ready??0;
    document.getElementById('stat-pending').textContent = v.pending??0;
    document.getElementById('stat-failed').textContent = v.failed??0;
  }catch(e){console.warn('stats',e)}
}

async function loadList(){
  const q = document.getElementById('q').value.trim();
  const st = document.getElementById('f-status').value;
  const params = new URLSearchParams();
  if(st) params.set('status', st);
  params.set('limit', '200');
  // Empty q → admin-list (full listing, no embedding). Non-empty q → admin-semantic-search.
  const endpoint = q ? '/webhook/admin-semantic-search' : '/webhook/admin-list';
  if (q) params.set('q', q);
  currentQuery = q;
  try{
    const data = await api(endpoint+'?'+params.toString());
    allRows = Array.isArray(data)?data:((data&&data.data)||[]);
    render(q ? 'semantic' : 'list');
  }catch(e){
    document.getElementById('tbody').innerHTML = \`<tr><td colspan="9" class="empty"><h3>โหลดไม่สำเร็จ</h3>\${esc(e.message)}</td></tr>\`;
  }
}

function render(mode){
  const tb = document.getElementById('tbody');
  if(!allRows.length){
    const msg = (mode === 'semantic') ? 'ไม่พบเอกสารที่คล้ายกัน' : 'ไม่มีเอกสาร';
    const hint = (mode === 'semantic') ? 'ลองค้นหาด้วยคำอื่น' : 'อัปโหลดผ่าน LINE OA เพื่อเริ่มต้น';
    tb.innerHTML = \`<tr><td colspan="9" class="empty"><h3>\${esc(msg)}</h3>\${esc(hint)}</td></tr>\`;
    return;
  }
  // Build match snippet: find query in top_chunk_content, show ~20
  // chars context on each side with <mark> wrapping the match.
  function buildMatch(r){
    if(mode !== 'semantic') return '<td style="color:var(--muted)">—</td>';
    const q = (currentQuery||'').trim();
    const txt = r.top_chunk_content || '';
    if(!txt) return '<td style="color:var(--muted)">—</td>';
    if(q){
      const safe = q.replace(/[.*+?^\${}()|[\]\\]/g, '\\$&');
      const re = new RegExp(safe, 'i');
      const m = re.exec(txt);
      if(m){
        const start = Math.max(0, m.index - 20);
        const end = Math.min(txt.length, m.index + q.length + 20);
        const before = (start > 0 ? '…' : '') + txt.slice(start, m.index);
        const matchTxt = txt.slice(m.index, m.index + q.length);
        const after = txt.slice(m.index + q.length, end) + (end < txt.length ? '…' : '');
        return \`<td><div class="match-cell" title="\${esc(txt.slice(0,200))}">\${esc(before)}<mark class="match">\${esc(matchTxt)}</mark>\${esc(after)}</div></td>\`;
      }
    }
    if(r.keyword_sim && parseFloat(r.keyword_sim) > 0){
      return \`<td style="color:var(--muted);font-size:12px">semantic match · kw \${(parseFloat(r.keyword_sim)).toFixed(1)}</td>\`;
    }
    return '<td style="color:var(--muted)">—</td>';
  }
  // Similarity: use vector_sim (cosine 0-1). RRF score is meaningless
  // for human display (always ~3% for top-ranked results).
  function buildSim(r){
    if(mode !== 'semantic') return '<td style="color:var(--muted)">—</td>';
    const v = parseFloat(r.vector_sim != null ? r.vector_sim : (r.similarity || 0));
    const pct = Math.max(0, Math.min(100, Math.round(v * 100)));
    return \`<td><div style="display:flex;align-items:center"><div class="similarity-bar"><span style="width:\${pct}%"></span></div><span style="font-variant-numeric:tabular-nums;font-size:12px;color:var(--muted)">\${pct}%</span></div></td>\`;
  }
  tb.innerHTML = allRows.map(r=>{
    return \`
    <tr>
      <td class="mono">\${esc(r.doc_no||'—')}</td>
      <td><div class="name">\${esc(r.file_name||'')}<small>\${esc(r.file_type||'')}\${r.size_bytes?' • '+Math.round(r.size_bytes/1024)+' KB':''}</small></div></td>
      \${buildSim(r)}
      \${buildMatch(r)}
      <td>\${esc(r.category||'—')}</td>
      <td><span class="badge \${esc(r.status||'pending')}">\${esc(r.status||'pending')}</span></td>
      <td style="text-align:right;font-variant-numeric:tabular-nums">\${r.chunk_count??0}</td>
      <td class="mono">\${fmtDate(r.uploaded_at)}</td>
      <td><div class="row-actions">
        <button class="btn ghost sm" onclick="view('\${esc(r.id)}')">ดู</button>
        <button class="btn sm" onclick="edit('\${esc(r.id)}')">แก้ไข</button>
        <button class="btn danger sm" onclick="del('\${esc(r.id)}','\${esc(r.file_name||'')}')">ลบ</button>
      </div></td>
    </tr>
  \`}).join('');
}

