// Wrap list results - always output 1 item even if empty
let items = $input.all().map(i => i.json);
// Filter out dummy rows (where id IS NULL)
items = items.filter(it => it && it.id != null);
return [{json: {ok: true, action: 'list', count: items.length, data: items}}];

// Wrap get result - returns null if no row found
const items = $input.all().map(i => i.json).filter(it => it && it.id != null);
return [{json: {ok: items.length > 0, action: 'get', data: items[0] || null}}];

// Wrap update result
const items = $input.all().map(i => i.json);
return [{json: {ok: true, action: 'update', data: items[0] || null}}];

// Wrap delete result
const items = $input.all().map(i => i.json);
return [{json: {ok: true, action: 'delete', data: items[0] || null}}];

// Wrap stats result - always output 1 item
const items = $input.all().map(i => i.json);
return [{json: {ok: true, action: 'stats', data: items[0] || {total: 0, ready: 0, pending: 0, failed: 0}}}];

// minio_key is computed in SQL (short string, ~26 chars, not ref-compressed).
// Just copy it to _minio_key for MinIO Delete.
const data = $input.first().json;
const minioKey = data.minio_key && data.minio_key.startsWith('law/contracts/') ? data.minio_key : null;
return [{
  json: {
    ...data,
    _minio_bucket: data.storage_bucket,
    _minio_key: minioKey,
    _skip_minio_delete: !minioKey
  }
}];

// Build binary file response from law.contracts.file_data (Postgres bytea).
const item = $input.first();
const json = item?.json || {};
let mime = json.file_mime || (json.file_type === 'pdf' ? 'application/pdf' : 'application/octet-stream');
let fileName = json.file_name || 'document';
let fileDataB64 = json.file_data_b64 || '';

if (!fileDataB64) {
  const message = 'No file_data stored in Postgres for this document. Re-upload or backfill law.contracts.file_data.';
  fileDataB64 = Buffer.from(message, 'utf8').toString('base64');
  mime = 'text/plain; charset=utf-8';
  fileName = 'missing-file.txt';
}

const fileSize = Buffer.from(fileDataB64, 'base64').length;
return [{
  json: { file_name: fileName, file_mime: mime, file_size: fileSize },
  binary: {
    data: {
      data: fileDataB64,
      mimeType: mime,
      fileName,
      fileSize,
    }
  }
}];

const wrapped = $input.first().json;
const q = wrapped._query || wrapped.query || {};
const body = wrapped._body || wrapped.body || wrapped || {};
const query = (q.q || body.q || "").toString().trim();
const limit = parseInt(q.limit || body.limit || 20, 10) || 20;
return [{json: {query, _query: query, _limit: limit}}];

const row = $input.first().json;
let result;
try {
  result = JSON.parse(row.result_json || '{"ok":true,"count":0,"data":[]}');
} catch(e) {
  return [{json: {ok: false, error: "parse_failed", message: e.message, data: []}}];
}
return [{json: result}];
